14	 *  when a sheet total moved; nothing when no figure moved. */
15	public class RecordRollup {
16	    public void record(@PathVariable("sheetId") String sheetId,
17	            @RequestParam(name = "by", required = false) String by, @Val Rollup before,
18	            PersonRepository people, ClaimRepository claims, RateRepository rates,
