47	/** The sheet's figures at one moment, as the screen shows them: each person's claimed and
48	 *  due-total (null: n/a; else at most the sheet's cap) and overdue-total, in the order they were added, and the
49	 *  sheet's claimed-total, due-total and overdue-total (these two leave out the single highest and
50	 *  lowest person's figure when three or more people have one). */
51	public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
52	
53	    /** A person's figures: their name, claimed, due-total (null: n/a) and overdue-total (the shown
54	     *  dues of their open claims past their due-by plus grace days on the sheet's today, n/a ones skipped). */
55	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
56	        public boolean sameAs(Figures other) {
57	            return other != null && claimed.equals(other.claimed)
58	                    && (dueTotal == null ? other.dueTotal == null : dueTotal.equals(other.dueTotal))
59	                    && overdueTotal.equals(other.overdueTotal);
60	        }
61	    }
62	
63	    /** The sheet's figures now. */
64	    public static Rollup of(String sheetId, PersonRepository people, ClaimRepository claims,
65	            RateRepository rates, SheetRepository sheets, SettingRepository settings) {
66	        List<Rate> sheetRates = rates.list(sheetId);
67	        DatedSetting floor = settings.floor(sheetId);
68	        BigDecimal cap = settings.cap(sheetId);
69	        LocalDate todayDate = sheets.today(sheetId);
70	        String today = todayDate.toString();
71	        Dues.Late late = settings.late(sheetId, todayDate);
72	        List<Claim> all = claims.list(sheetId);
73	        Map<Long, Figures> figures = new LinkedHashMap<>();
74	        BigDecimal claimedTotal = zero();
75	        List<BigDecimal> dues = new ArrayList<>();
76	        List<BigDecimal> overdues = new ArrayList<>();
77	        for (Person p : people.list(sheetId)) {
78	            BigDecimal claimed = zero();
79	            BigDecimal due = zero();
80	            BigDecimal overdue = zero();
81	            boolean kept = false;
82	            for (Claim c : all) {
83	                if (c.getPersonId() != p.getId() || !p.countsLive(c)) continue;
84	                claimed = claimed.add(new BigDecimal(c.getAmount()));
85	                String grade = p.gradeOn(c.getDate());
86	                String pct = rateOn(sheetRates, grade, c.getDate());
87	                String d = Dues.shown(c, pct == null ? null : Dues.of(c.getAmount(), pct, late.rounding(c.getRoundDate())), floor.on(c.getDate()), late);
88	                kept |= c.getSettledDue() != null || c.isBound()
89	                        || (pct != null && (!grade.equals(p.getGrade()) || c.getDate().compareTo(today) <= 0));
90	                if (d != null) due = due.add(new BigDecimal(d));
91	                if (d != null && ClaimStatus.isOpen(c.getStatus()) && late.lateFrom(c).isBefore(todayDate)) {
92	                    overdue = overdue.add(new BigDecimal(d));
93	                }
94	            }
95	            boolean na = rateOn(sheetRates, p.getGrade(), today) == null && !kept;
96	            if (cap != null && due.compareTo(cap) > 0) due = cap.setScale(2);
97	            figures.put(p.getId(), new Figures(p.getName(), claimed.toPlainString(),
98	                    na ? null : due.toPlainString(), overdue.toPlainString()));
99	            claimedTotal = claimedTotal.add(claimed);
100	            if (!na) dues.add(due);
101	            overdues.add(overdue);
102	        }
103	        return new Rollup(figures, claimedTotal.toPlainString(), trimmedSum(dues).toPlainString(),
104	                trimmedSum(overdues).toPlainString());
105	    }
106	
107	    /** The audit lines after a change from {@code before} to this: one ROLLUP per person whose
108	     *  figures moved (a new person counts as moved), then TOTALS when a sheet total moved. */
109	    public List<String> changesSince(Rollup before, String sheetId, String by) {
110	        String head = " sheet=" + sheetId + " by=" + by;
111	        List<String> lines = new ArrayList<>();
112	        people.forEach((id, now) -> {
113	            if (!now.sameAs(before.people.get(id))) {
114	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
115	                        + " due-total=" + (now.dueTotal() == null ? "n/a" : now.dueTotal())
116	                        + " overdue-total=" + now.overdueTotal());
117	            }
118	        });
119	        if (!claimedTotal.equals(before.claimedTotal) || !dueTotal.equals(before.dueTotal)
120	                || !overdueTotal.equals(before.overdueTotal)) {
121	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
122	                    + " overdue-total=" + overdueTotal);
123	        }
124	        return lines;
125	    }
