127	    /** The grade's rate in force on the date (yyyy-MM-dd), inherited up the parent chain; null when none. */
128	    private static String rateOn(List<Rate> rates, String grade, String date) {
129	        Rate found = RateRepository.inForce(rates, grade, date);
130	        return found == null ? null : found.pct();
131	    }
132	
133	    /** The figures added up, leaving out the single highest and the single lowest when there are three or more. */
134	    private static BigDecimal trimmedSum(List<BigDecimal> figures) {
135	        List<BigDecimal> sorted = new ArrayList<>(figures);
136	        sorted.sort(BigDecimal::compareTo);
137	        if (sorted.size() >= 3) sorted = sorted.subList(1, sorted.size() - 1);
138	        BigDecimal total = zero();
139	        for (BigDecimal f : sorted) total = total.add(f);
140	        return total;
141	    }
142	
143	    private static BigDecimal zero() {
144	        return BigDecimal.ZERO.setScale(2);
145	    }
146	}
