255	                }, sheetId, id, asOf);
256	        person.setGrades(new ArrayList<>(grades), asOf);
257	        person.setHolds(new ArrayList<>(jdbc.query("SELECT from_date, to_date FROM person_hold WHERE sheet_id = ? "
258	                + "AND person_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY id", (rs, n) -> {
259	                    LocalDate to = rs.getObject("to_date", LocalDate.class);
260	                    return new Hold(rs.getObject("from_date", LocalDate.class).toString(), to == null ? null : to.toString());
261	                }, sheetId, id, asOf)));
