359	    /** Add a person with their grade (from the beginning of time), own terms (null: none) and
360	     *  contact (null: none). */
361	    public Person add(String sheetId, String name, String grade, Integer terms, String contact, String user) {
362	        GeneratedKeyHolder key = new GeneratedKeyHolder();
363	        jdbc.update(con -> {
364	            PreparedStatement ps = con.prepareStatement(
365	                    "INSERT INTO person (sheet_id, name, created_by, terms, contact, added_on) "
366	                            + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
367	                    new String[] { "id" });
368	            ps.setString(1, sheetId);
369	            ps.setString(2, name);
370	            ps.setString(3, user);
371	            ps.setObject(4, terms);
372	            ps.setString(5, contact);
373	            ps.setString(6, sheetId);
374	            return ps;
375	        }, key);
376	        long id = key.getKey().longValue();
377	        // The first grade a person is given applies from the beginning of time.
378	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by) VALUES (?, ?, ?, NULL, ?)",
379	                sheetId, id, grade, user);
380	        gradeHistory(sheetId, id, grade, null);
381	        Person person = new Person(id, sheetId, name, grade, 0);
382	        person.getGrades().add(new GradeFrom(grade, null));
383	        person.setTerms(terms);
384	        person.setContact(contact);
385	        return person;
386	    }
