391	        LocalDate from = given.from() == null ? null : LocalDate.parse(given.from());
392	        if (from == null) {
393	            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date IS NULL",
394	                    person.getSheetId(), person.getId());
395	        } else {
396	            jdbc.update("DELETE FROM person_grade WHERE sheet_id = ? AND person_id = ? AND from_date = ?",
397	                    person.getSheetId(), person.getId(), from);
398	        }
399	        jdbc.update("INSERT INTO person_grade (sheet_id, person_id, grade, from_date, set_by) VALUES (?, ?, ?, ?, ?)",
400	                person.getSheetId(), person.getId(), given.grade(), from, user);
401	        gradeHistory(person.getSheetId(), person.getId(), given.grade(), from);
402	    }
