405	    private void gradeHistory(String sheetId, long personId, String grade, LocalDate from) {
406	        jdbc.update("INSERT INTO person_grade_history (sheet_id, person_id, grade, from_date, on_date) "
407	                + "VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", sheetId, personId, grade, from, sheetId);
