410	    /** Save the person over the version it was loaded at, raising the version; false (nothing
411	     *  written) when someone else has saved the person since. */
412	    public boolean update(Person person) {
413	        int n = jdbc.update(
414	                "UPDATE person SET name = ?, terms = ?, contact = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
415	                person.getName(), person.getTerms(), person.getContact(), person.getSheetId(), person.getId(), person.getVersion());
416	        if (n == 0) {
417	            return false;
418	        }
419	        person.setVersion(person.getVersion() + 1);
420	        return true;
