430	    /** Drop the person's last statement kept, and load the one before it into the person (none: they
431	     *  show no statement); their count goes down by one (not an edit: the version stays). */
432	    public void cancelStatement(Person person) {
433	        List<Long> kept = jdbc.queryForList(
434	                "SELECT id FROM person_statement WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC LIMIT 2",
435	                Long.class, person.getSheetId(), person.getId());
436	        if (!kept.isEmpty()) {
437	            jdbc.update("DELETE FROM person_statement WHERE id = ?", kept.get(0));
438	        }
439	        String[] before = kept.size() < 2 ? null : jdbc.queryForObject(
440	                "SELECT stated_total, statement_date FROM person_statement WHERE id = ?",
441	                (rs, n) -> new String[] { rs.getString("stated_total"),
442	                        rs.getObject("statement_date", LocalDate.class).toString() }, kept.get(1));
443	        person.unstated(before == null ? null : before[0], before == null ? null : before[1]);
444	        saveStatements(person);
445	    }
