447	    private void saveStatements(Person person) {
448	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
449	                person.getStatementCount(), person.getStatedTotal(),
450	                person.getStatementDate() == null ? null : LocalDate.parse(person.getStatementDate()),
451	                person.getSheetId(), person.getId());
452	    }
