454	    /** Save the person's retirement date (not an edit: the version stays). */
455	    public void updateRetired(Person person) {
456	        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?",
457	                LocalDate.parse(person.getRetiredFrom()), person.getSheetId(), person.getId());
458	        jdbc.update("INSERT INTO person_retired_history (sheet_id, person_id, retired_from, on_date) "
459	                + "VALUES (?, ?, ?, (SELECT today FROM sheet WHERE id = ?))", person.getSheetId(), person.getId(),
460	                LocalDate.parse(person.getRetiredFrom()), person.getSheetId());
461	    }
462	
463	    /** Add a hold on the person (not an edit: the version stays). */
464	    public void addHold(Person person, Hold hold, String user) {
465	        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, held_by, added_on) "
466	                + "VALUES (?, ?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
467	                person.getSheetId(), person.getId(), LocalDate.parse(hold.from()),
468	                hold.to() == null ? null : LocalDate.parse(hold.to()), user, person.getSheetId());
469	        person.getHolds().add(hold);
470	    }
471	
472	    /** Merge the person {@code from} into {@code into}: from's name and aliases become into's aliases;
473	     *  from's patrons are added to into's (not into themselves, no repeats); anyone naming from as
474	     *  patron names into instead (no repeats); from's statements, holds, watchers, grades and the
475	     *  person themselves are dropped. Their claims, pool memberships and period totals must have
476	     *  moved first. */
477	    public void merge(Person from, Person into, String user) {
478	        String sheetId = into.getSheetId();
479	        jdbc.update("INSERT INTO person_alias (sheet_id, person_id, alias, added_by) VALUES (?, ?, ?, ?)",
480	                sheetId, into.getId(), from.getName(), user);
481	        jdbc.update("UPDATE person_alias SET person_id = ? WHERE sheet_id = ? AND person_id = ?",
482	                into.getId(), sheetId, from.getId());
483	        for (Long patronId : from.getPatronIds()) {
484	            if (patronId != into.getId() && !into.getPatronIds().contains(patronId)) {
485	                jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
486	                        sheetId, into.getId(), patronId, user);
487	                into.getPatronIds().add(patronId);
488	            }
489	        }
490	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
491	        // Whoever named from names into instead, unless that is into themselves or they name into already.
492	        jdbc.update("DELETE FROM person_patron WHERE sheet_id = ? AND patron_id = ? AND (person_id = ? OR person_id IN "
493	                + "(SELECT k.person_id FROM person_patron k WHERE k.sheet_id = ? AND k.patron_id = ?))",
494	                sheetId, from.getId(), into.getId(), sheetId, into.getId());
495	        jdbc.update("UPDATE person_patron SET patron_id = ? WHERE sheet_id = ? AND patron_id = ?",
496	                into.getId(), sheetId, from.getId());
497	        into.getPatronIds().remove(Long.valueOf(from.getId()));
498	        for (String table : List.of("person_statement", "person_hold", "person_watch", "person_grade",
499	                "person_grade_history", "person_retired_history")) {
500	            jdbc.update("DELETE FROM " + table + " WHERE sheet_id = ? AND person_id = ?", sheetId, from.getId());
501	        }
502	        jdbc.update("DELETE FROM person WHERE sheet_id = ? AND id = ?", sheetId, from.getId());
503	        withAliases(sheetId, List.of(into));
504	    }
505	}
