577	
578	    /** Their grades, by from-date (none first), and the one in force on the sheet's today. */
579	    public void setGrades(java.util.List<GradeFrom> grades, java.time.LocalDate today) {
580	        this.grades = grades;
581	        this.grade = gradeOn(today.toString());
582	        this.today = today;
583	    }
584	
585	    /** The grade in force on the date (yyyy-MM-dd): the one with the latest from-date on or before
586	     *  it; null when there is none. */
587	    public String gradeOn(String date) {
588	        GradeFrom found = null;
589	        for (GradeFrom g : grades) {
590	            if (g.from() != null && g.from().compareTo(date) > 0) continue;
591	            if (found == null || (found.from() == null ? "" : found.from()).compareTo(g.from() == null ? "" : g.from()) < 0) found = g;
592	        }
593	        return found == null ? null : found.grade();
594	    }
595	
596	    /** Give them the grade from the from-date (null: the beginning of time), replacing the one
597	     *  with the same from-date; the save records it. */
598	    public void giveGrade(String grade, String from, java.time.LocalDate today) {
599	        java.util.List<GradeFrom> now = new java.util.ArrayList<>(grades);
600	        now.removeIf((g) -> java.util.Objects.equals(g.from(), from));
601	        now.add(new GradeFrom(grade, from));
602	        now.sort(java.util.Comparator.comparing((GradeFrom g) -> g.from() == null ? "" : g.from()));
603	        setGrades(now, today);
604	        recorded = new GradeFrom(grade, from);
605	    }
606	
607	    public Integer getTerms() { return terms; }
608	    public void setTerms(Integer terms) { this.terms = terms; }
609	
610	    /** Give them these terms (null: none); the audit line records them when they changed. */
611	    public void giveTerms(Integer terms) {
612	        termsChanged = !java.util.Objects.equals(this.terms, terms);
613	        this.terms = terms;
614	    }
615	
616	    @JsonIgnore
617	    public boolean isTermsChanged() { return termsChanged; }
618	
619	    public String getContact() { return contact; }
620	    public void setContact(String contact) { this.contact = contact; }
621	
622	    /** Give them this contact (null: none); the audit line records it when it changed. */
623	    public void giveContact(String contact) {
624	        contactChanged = !java.util.Objects.equals(this.contact, contact);
625	        this.contact = contact;
626	    }
627	
628	    @JsonIgnore
629	    public boolean isContactChanged() { return contactChanged; }
630	
631	    @JsonIgnore
632	    public GradeFrom getRecorded() { return recorded; }
633	    public long getVersion() { return version; }
634	    public void setVersion(long version) { this.version = version; }
635	    public int getStatementCount() { return statementCount; }
636	    public String getStatedTotal() { return statedTotal; }
637	    public String getStatementDate() { return statementDate; }
638	    public String getRetiredFrom() { return retiredFrom; }
639	    public void setRetiredFrom(String retiredFrom) { this.retiredFrom = retiredFrom; }
640	    public boolean isRetired() { return retiredFrom != null; }
641	    /** Whether the sheet's today is on or after their retirement date: their open claims no statement
642	     *  bound then count in no live total. */
643	    public boolean isRetiredReached() {
644	        return retiredFrom != null && today != null && !today.isBefore(java.time.LocalDate.parse(retiredFrom));
645	    }
646	    /** Whether they have any hold. */
647	    public boolean isHeld() { return !holds.isEmpty(); }
648	    public java.util.List<Hold> getHolds() { return holds; }
649	    public void setHolds(java.util.List<Hold> holds) { this.holds = holds; }
650	    public java.util.List<Long> getPatronIds() { return patronIds; }
651	    public void setPatronIds(java.util.List<Long> patronIds) { this.patronIds = patronIds; }
652	    public java.util.List<String> getAliases() { return aliases; }
653	    public void setAliases(java.util.List<String> aliases) { this.aliases = aliases; }
654	
655	    /** Whether the claim counts in live totals: it counts by status, and is not an open (OPEN or
656	     *  PENDING) claim dated within one of their holds, or of a person whose retirement date is reached,
657	     *  that no statement bound, nor a deferred one. */
658	    public boolean countsLive(Claim claim) {
659	        return claim.isCounting() && !leftOutLive(claim);
660	    }
661	
662	    /** Whether the live rules leave the claim out whatever its status counts: it is deferred, or an
663	     *  open (OPEN or PENDING) claim that no statement bound, dated within one of their holds or of a
664	     *  person whose retirement date the sheet's today has reached. */
665	    public boolean leftOutLive(Claim claim) {
666	        return claim.isDeferred()
667	                || (ClaimStatus.isOpen(claim.getStatus()) && !claim.isStated()
668	                        && (isRetiredReached() || holds.stream().anyMatch((h) -> h.covers(claim.getDate()))));
669	    }
670	
671	    /** Whether a claim on this date is refused: the person is retired from a date before it. */
672	    public boolean retiredBefore(java.time.LocalDate date) {
673	        return retiredFrom != null && date.isAfter(java.time.LocalDate.parse(retiredFrom));
674	    }
